// Lifecycle status of a single table.
enum TableStatus {
    AVAILABLE, // free to be assigned
    OCCUPIED   // currently seating a party
}

// A single seating unit on the restaurant floor.
class Table {
    private final String tableId; // unique id, e.g. T2-1
    private final int capacity;   // maximum party size it seats
    private TableStatus status;   // current lifecycle state

    public Table(String tableId, int capacity) {
        this.tableId = tableId;   // store id
        this.capacity = capacity;  // store capacity
        this.status = TableStatus.AVAILABLE; // new tables start free
    }

    public String getTableId() { return tableId; }     // id getter
    public int getCapacity() { return capacity; }        // capacity getter
    public TableStatus getStatus() { return status; }    // status getter
    public void setStatus(TableStatus status) { this.status = status; } // status setter
    public boolean isAvailable() { return status == TableStatus.AVAILABLE; } // convenience check
}

// A purchasable dish with a price and a kitchen preparation time.
class MenuItem {
    private final String name;         // dish name, doubles as its id
    private final double price;        // price charged per unit
    private final int prepTimeMinutes; // minutes to prepare one unit

    public MenuItem(String name, double price, int prepTimeMinutes) {
        this.name = name;                     // store name
        this.price = price;                    // store price
        this.prepTimeMinutes = prepTimeMinutes; // store prep time
    }

    public String getName() { return name; }                   // name getter
    public double getPrice() { return price; }                   // price getter
    public int getPrepTimeMinutes() { return prepTimeMinutes; }   // prep time getter
}

// Creates tables with capacity-prefixed ids.
class TableFactory {
    private final java.util.Map<Integer, Integer> counters = new java.util.HashMap<>(); // capacity -> count so far

    public java.util.List<Table> createTables(int capacity, int count) {
        java.util.List<Table> created = new java.util.ArrayList<>(); // result list
        for (int i = 0; i < count; i++) {                              // create 'count' tables
            int n = counters.getOrDefault(capacity, 0) + 1;              // next number for this capacity
            counters.put(capacity, n);                                    // remember it
            created.add(new Table("T" + capacity + "-" + n, capacity));    // e.g. T2-1
        }
        return created; // hand back the new tables
    }
}

