// Strategy interface: how a table is chosen for a party size.
interface TableAssignmentStrategy {
    // Returns the chosen table, or null if none of the available tables fit.
    Table assignTable(int partySize, java.util.Collection<Table> availableTables);
}

// Picks the smallest-capacity available table that still fits the party.
class BestFitTableAssignmentStrategy implements TableAssignmentStrategy {
    @Override
    public Table assignTable(int partySize, java.util.Collection<Table> availableTables) {
        Table best = null;                                    // smallest qualifying table found so far
        for (Table t : availableTables) {                       // scan all available tables
            if (t.getCapacity() >= partySize) {                    // this table fits the party
                if (best == null || t.getCapacity() < best.getCapacity()) { // smaller than current best
                    best = t;                                          // remember it
                }
            }
        }
        return best; // the best-fit table, or null if none fit
    }
}

// A set of menu items ordered by a table, tracked through the kitchen.
class Order {
    private final String orderId;                                       // unique id
    private final String tableId;                                       // which table placed it
    private final java.util.List<MenuItem> items;                        // items ordered
    private int estimatedReadyMinutes;                                    // estimate computed at placement time
    private String status;                                                // QUEUED, READY

    public Order(String orderId, String tableId, java.util.List<MenuItem> items) {
        this.orderId = orderId;   // store id
        this.tableId = tableId;    // store table
        this.items = items;        // store items
        this.status = "QUEUED";     // starts queued
    }

    public String getOrderId() { return orderId; }                      // id getter
    public String getTableId() { return tableId; }                       // table getter
    public java.util.List<MenuItem> getItems() { return items; }         // items getter
    public int getEstimatedReadyMinutes() { return estimatedReadyMinutes; } // estimate getter
    public void setEstimatedReadyMinutes(int minutes) { this.estimatedReadyMinutes = minutes; } // estimate setter
    public String getStatus() { return status; }                          // status getter
    public void setStatus(String status) { this.status = status; }         // status setter

    // The order's own prep time: items cook in parallel, so it's the slowest single item.
    public int ownPrepTimeMinutes() {
        int max = 0;                                     // running maximum
        for (MenuItem item : items) {                      // scan all items
            max = Math.max(max, item.getPrepTimeMinutes()); // track the slowest one
        }
        return max; // this order's own prep time
    }

    public double subtotal() {
        double total = 0.0;                    // running total
        for (MenuItem item : items) {             // scan all items
            total += item.getPrice();               // add each item's price
        }
        return total; // sum of item prices
    }
}

// The final computed charge for a table's order(s).
class Bill {
    private final double subtotal; // sum of item prices
    private final double tax;      // flat percentage of subtotal

    public Bill(double subtotal, double tax) {
        this.subtotal = subtotal; // store subtotal
        this.tax = tax;             // store tax
    }

    public double getSubtotal() { return subtotal; } // subtotal getter
    public double getTax() { return tax; }             // tax getter
    public double getTotal() { return subtotal + tax; } // subtotal plus tax
}

