// Observer interface: reacts to restaurant lifecycle events.
interface RestaurantObserver {
    void onTableAssigned(Table table, int partySize);         // table seated
    void onAssignmentRejected(int partySize, String reason);   // no fitting table
    void onOrderPlaced(Order order);                            // order queued
    void onBillGenerated(String tableId, Bill bill);            // table closed
}

// Simple observer that prints events to the console.
class ConsoleRestaurantObserver implements RestaurantObserver {
    @Override
    public void onTableAssigned(Table table, int partySize) {
        System.out.println("Table " + table.getTableId() + " assigned for party of " + partySize);
    }

    @Override
    public void onAssignmentRejected(int partySize, String reason) {
        System.out.println("Assignment rejected for party of " + partySize + ": " + reason);
    }

    @Override
    public void onOrderPlaced(Order order) {
        System.out.println("Order " + order.getOrderId() + " placed for " + order.getTableId() + ", estimated ready in " + order.getEstimatedReadyMinutes() + " minutes");
    }

    @Override
    public void onBillGenerated(String tableId, Bill bill) {
        System.out.println("Bill for " + tableId + ": subtotal " + bill.getSubtotal() + ", tax " + bill.getTax() + ", total " + bill.getTotal());
    }
}

// Custom exceptions for the realistic failure modes.
class NoTableAvailableException extends RuntimeException {
    public NoTableAvailableException(String msg) { super(msg); }
}
class InvalidOrderException extends RuntimeException {
    public InvalidOrderException(String msg) { super(msg); }
}
class TableNotOccupiedException extends RuntimeException {
    public TableNotOccupiedException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class RestaurantService {
    private final java.util.Map<String, Table> tables = new java.util.HashMap<>();       // tableId -> Table
    private final java.util.Map<String, Order> orders = new java.util.HashMap<>();       // orderId -> Order
    private final java.util.Map<String, java.util.List<Order>> tableOrders = new java.util.HashMap<>(); // tableId -> all its orders, for billing
    private final java.util.List<Order> kitchenQueue = new java.util.ArrayList<>();        // FIFO of orders not yet ready
    private final TableAssignmentStrategy assignmentStrategy;   // pluggable seating policy
    private final java.util.List<RestaurantObserver> observers = new java.util.ArrayList<>(); // listeners
    private int orderCounter = 0; // simple id generator

    public RestaurantService(TableAssignmentStrategy assignmentStrategy) {
        this.assignmentStrategy = assignmentStrategy; // store chosen policy
    }

    public void addTable(Table table) { tables.put(table.getTableId(), table); tableOrders.put(table.getTableId(), new java.util.ArrayList<>()); } // register a table
    public void addObserver(RestaurantObserver observer) { observers.add(observer); } // register a listener

    // Assigns the smallest fitting available table to a party, or throws.
    public synchronized Table assignTable(int partySize) {
        java.util.List<Table> available = new java.util.ArrayList<>(); // currently free tables
        for (Table t : tables.values()) {                                // scan all tables
            if (t.isAvailable()) available.add(t);                         // collect the free ones
        }
        Table chosen = assignmentStrategy.assignTable(partySize, available); // ask the strategy
        if (chosen == null) {                                              // nothing fits
            for (RestaurantObserver obs : observers) obs.onAssignmentRejected(partySize, "No table available"); // notify
            throw new NoTableAvailableException("No table available for party size " + partySize);
        }
        chosen.setStatus(TableStatus.OCCUPIED);                             // claim the table
        for (RestaurantObserver obs : observers) obs.onTableAssigned(chosen, partySize); // notify
        return chosen; // hand back to caller
    }

    // Places an order, queues it behind existing orders, and estimates a ready time.
    public synchronized Order placeOrder(String tableId, java.util.List<MenuItem> items) {
        if (items == null || items.isEmpty()) throw new InvalidOrderException("Order must contain at least one item");
        if (!tables.containsKey(tableId)) throw new InvalidOrderException("Unknown table: " + tableId);
        orderCounter++;                                                     // bump id counter
        String orderId = "ORD-" + orderCounter;                             // build id
        Order order = new Order(orderId, tableId, items);                   // build order
        int aheadMinutes = 0;                                                 // total prep time of orders already queued
        for (Order queued : kitchenQueue) aheadMinutes += queued.ownPrepTimeMinutes(); // sum preceding orders
        order.setEstimatedReadyMinutes(aheadMinutes + order.ownPrepTimeMinutes()); // this order waits behind all of them
        kitchenQueue.add(order);                                             // enqueue FIFO
        orders.put(orderId, order);                                          // store it
        tableOrders.get(tableId).add(order);                                 // track for billing
        for (RestaurantObserver obs : observers) obs.onOrderPlaced(order);  // notify
        return order; // hand back to caller
    }

    // Removes a finished order from the kitchen queue.
    public synchronized void markOrderReady(String orderId) {
        Order order = orders.get(orderId);                                 // look up order
        order.setStatus("READY");                                            // mark ready
        kitchenQueue.remove(order);                                           // leave the queue
    }

    // Computes the bill for all orders placed at a table, then frees the table.
    public synchronized Bill closeTable(String tableId) {
        Table table = tables.get(tableId);                                  // look up table
        if (table == null || table.getStatus() != TableStatus.OCCUPIED) {
            throw new TableNotOccupiedException("Table " + tableId + " is not currently occupied");
        }
        double subtotal = 0.0;                                                // running subtotal
        for (Order order : tableOrders.get(tableId)) subtotal += order.subtotal(); // sum all orders at this table
        double tax = subtotal * 0.08;                                          // flat 8 percent tax
        Bill bill = new Bill(subtotal, tax);                                    // build bill
        table.setStatus(TableStatus.AVAILABLE);                                 // free the table
        for (RestaurantObserver obs : observers) obs.onBillGenerated(tableId, bill); // notify
        return bill; // hand back to caller
    }
}

