using namespace std;

// Observer interface: reacts to restaurant lifecycle events.
class RestaurantObserver {
public:
    virtual void onTableAssigned(const Table& table, int partySize) = 0;
    virtual void onAssignmentRejected(int partySize, const string& reason) = 0;
    virtual void onOrderPlaced(const Order& order) = 0;
    virtual void onBillGenerated(const string& tableId, const Bill& bill) = 0;
    virtual ~RestaurantObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleRestaurantObserver : public RestaurantObserver {
public:
    void onTableAssigned(const Table& table, int partySize) override {
        cout << "Table " << table.tableId << " assigned for party of " << partySize << endl;
    }
    void onAssignmentRejected(int partySize, const string& reason) override {
        cout << "Assignment rejected for party of " << partySize << ": " << reason << endl;
    }
    void onOrderPlaced(const Order& order) override {
        cout << "Order " << order.orderId << " placed for " << order.tableId << ", estimated ready in " << order.estimatedReadyMinutes << " minutes" << endl;
    }
    void onBillGenerated(const string& tableId, const Bill& bill) override {
        cout << "Bill for " << tableId << ": subtotal " << bill.subtotal << ", tax " << bill.tax << ", total " << bill.getTotal() << endl;
    }
};

// Custom exceptions for the realistic failure modes.
class NoTableAvailableException : public runtime_error {
public: NoTableAvailableException(const string& msg) : runtime_error(msg) {}
};
class InvalidOrderException : public runtime_error {
public: InvalidOrderException(const string& msg) : runtime_error(msg) {}
};
class TableNotOccupiedException : public runtime_error {
public: TableNotOccupiedException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class RestaurantService {
    map<string, Table> tables;                        // tableId -> Table
    map<string, Order> orders;                         // orderId -> Order
    map<string, vector<string>> tableOrders;           // tableId -> orderIds, for billing
    vector<string> kitchenQueue;                        // FIFO of orderIds not yet ready
    shared_ptr<TableAssignmentStrategy> assignmentStrategy; // pluggable seating policy
    vector<shared_ptr<RestaurantObserver>> observers;   // listeners
    int orderCounter = 0;                                 // simple id generator

public:
    RestaurantService(shared_ptr<TableAssignmentStrategy> strategy) : assignmentStrategy(strategy) {}

    void addTable(Table table) { tables.insert({table.tableId, table}); tableOrders[table.tableId] = {}; } // register a table
    void addObserver(shared_ptr<RestaurantObserver> observer) { observers.push_back(observer); } // register a listener

    Table assignTable(int partySize) {
        vector<Table*> available;                          // currently free tables
        for (auto& entry : tables) {                          // scan all tables
            if (entry.second.isAvailable()) available.push_back(&entry.second); // collect the free ones
        }
        Table* chosen = assignmentStrategy->assignTable(partySize, available); // ask the strategy
        if (chosen == nullptr) {                                // nothing fits
            for (auto& obs : observers) obs->onAssignmentRejected(partySize, "No table available"); // notify
            throw NoTableAvailableException("No table available for party size " + to_string(partySize));
        }
        chosen->status = TableStatus::OCCUPIED;                 // claim the table
        for (auto& obs : observers) obs->onTableAssigned(*chosen, partySize); // notify
        return *chosen; // hand back to caller
    }

    Order placeOrder(string tableId, vector<MenuItem> items) {
        if (items.empty()) throw InvalidOrderException("Order must contain at least one item");
        if (tables.find(tableId) == tables.end()) throw InvalidOrderException("Unknown table: " + tableId);
        orderCounter++;                                          // bump id counter
        string orderId = "ORD-" + to_string(orderCounter);         // build id
        Order order(orderId, tableId, items);                       // build order
        int aheadMinutes = 0;                                         // total prep time of orders already queued
        for (auto& qId : kitchenQueue) aheadMinutes += orders.at(qId).ownPrepTimeMinutes(); // sum preceding orders
        order.estimatedReadyMinutes = aheadMinutes + order.ownPrepTimeMinutes(); // this order waits behind all of them
        kitchenQueue.push_back(orderId);                             // enqueue FIFO
        orders.insert({orderId, order});                              // store it
        tableOrders[tableId].push_back(orderId);                       // track for billing
        for (auto& obs : observers) obs->onOrderPlaced(orders.at(orderId)); // notify
        return orders.at(orderId); // hand back to caller
    }

    void markOrderReady(string orderId) {
        orders.at(orderId).status = "READY"; // mark ready
        kitchenQueue.erase(remove(kitchenQueue.begin(), kitchenQueue.end(), orderId), kitchenQueue.end()); // leave the queue
    }

    Bill closeTable(string tableId) {
        auto it = tables.find(tableId); // look up table
        if (it == tables.end() || it->second.status != TableStatus::OCCUPIED) {
            throw TableNotOccupiedException("Table " + tableId + " is not currently occupied");
        }
        double subtotal = 0.0;                                       // running subtotal
        for (auto& orderId : tableOrders[tableId]) subtotal += orders.at(orderId).subtotal(); // sum all orders at this table
        double tax = subtotal * 0.08;                                  // flat 8 percent tax
        Bill bill(subtotal, tax);                                       // build bill
        it->second.status = TableStatus::AVAILABLE;                     // free the table
        for (auto& obs : observers) obs->onBillGenerated(tableId, bill); // notify
        return bill; // hand back to caller
    }
};

