        service.addObserver(new ConsoleRestaurantObserver());

        TableFactory factory = new TableFactory();
        for (Table t : factory.createTables(2, 1)) service.addTable(t);
        for (Table t : factory.createTables(4, 1)) service.addTable(t);
        for (Table t : factory.createTables(6, 1)) service.addTable(t);
