class RestaurantService {
    private final Map<String, Table> tables = new HashMap<>();
    private final Map<String, Order> orders = new HashMap<>();
    private final Map<String, List<Order>> tableOrders = new HashMap<>();
    private final List<Order> kitchenQueue = new ArrayList<>();
    private final TableAssignmentStrategy assignmentStrategy;
    private final List<RestaurantObserver> observers = new ArrayList<>();
    private int orderCounter = 0;

    public RestaurantService(TableAssignmentStrategy assignmentStrategy) {
        this.assignmentStrategy = assignmentStrategy;
    }

    public void addTable(Table table) { tables.put(table.getTableId(), table); tableOrders.put(table.getTableId(), new ArrayList<>()); }
    public void addObserver(RestaurantObserver observer) { observers.add(observer); }

    public synchronized Table assignTable(int partySize) {
        List<Table> available = new ArrayList<>();
        for (Table t : tables.values()) {
            if (t.isAvailable()) available.add(t);
        }
        Table chosen = assignmentStrategy.assignTable(partySize, available);
        if (chosen == null) {
            for (RestaurantObserver obs : observers) obs.onAssignmentRejected(partySize, "No table available");
            throw new NoTableAvailableException("No table available for party size " + partySize);
        }
        chosen.setStatus(TableStatus.OCCUPIED);
        for (RestaurantObserver obs : observers) obs.onTableAssigned(chosen, partySize);
        return chosen;
    }

    public synchronized Order placeOrder(String tableId, List<MenuItem> items) {
        if (items == null || items.isEmpty()) throw new InvalidOrderException("Order must contain at least one item");
        if (!tables.containsKey(tableId)) throw new InvalidOrderException("Unknown table: " + tableId);
        orderCounter++;
        String orderId = "ORD-" + orderCounter;
        Order order = new Order(orderId, tableId, items);
        int aheadMinutes = 0;
        for (Order queued : kitchenQueue) aheadMinutes += queued.ownPrepTimeMinutes();
        order.setEstimatedReadyMinutes(aheadMinutes + order.ownPrepTimeMinutes());
        kitchenQueue.add(order);
        orders.put(orderId, order);
        tableOrders.get(tableId).add(order);
        for (RestaurantObserver obs : observers) obs.onOrderPlaced(order);
        return order;
    }

    public synchronized void markOrderReady(String orderId) {
        Order order = orders.get(orderId);
        order.setStatus("READY");
        kitchenQueue.remove(order);
    }

    public synchronized Bill closeTable(String tableId) {
        Table table = tables.get(tableId);
        if (table == null || table.getStatus() != TableStatus.OCCUPIED) {
            throw new TableNotOccupiedException("Table " + tableId + " is not currently occupied");
        }
        double subtotal = 0.0;
        for (Order order : tableOrders.get(tableId)) subtotal += order.subtotal();
        double tax = subtotal * 0.08;
        Bill bill = new Bill(subtotal, tax);
        table.setStatus(TableStatus.AVAILABLE);
        for (RestaurantObserver obs : observers) obs.onBillGenerated(tableId, bill);
        return bill;
    }
}

