    RestaurantService(shared_ptr<TableAssignmentStrategy> strategy) : assignmentStrategy(strategy) {}

    void addTable(Table table) { tables.insert({table.tableId, table}); tableOrders[table.tableId] = {}; }
    void addObserver(shared_ptr<RestaurantObserver> observer) { observers.push_back(observer); }

