        vector<Table*> available;
        for (auto& entry : tables) {
            if (entry.second.isAvailable()) available.push_back(&entry.second);
        }
        Table* chosen = assignmentStrategy->assignTable(partySize, available);
        if (chosen == nullptr) {
            for (auto& obs : observers) obs->onAssignmentRejected(partySize, "No table available");
            throw NoTableAvailableException("No table available for party size " + to_string(partySize));
        }
        chosen->status = TableStatus::OCCUPIED;
        for (auto& obs : observers) obs->onTableAssigned(*chosen, partySize);
        return *chosen;
    }

